type Tag = { id: string; src: string; maxKb: number; consent: ConsentKey };

// Each entry is a deliberate decision with a size it is allowed to cost.
// 'the marketing team asked for it' is not a budget.
const TAGS: Tag[] = [
  { id: 'analytics', src: 'https://cdn.example/a.js', maxKb: 12, consent: 'analytics' },
  { id: 'chat', src: 'https://cdn.example/chat.js', maxKb: 60, consent: 'functional' },
];

export function loadThirdParty(consent: Consent) {
  // After interactive, in idle time. A tag in <head> delays the first paint
  // of the product the customer came to buy.
  const whenIdle = window.requestIdleCallback ?? ((cb: () => void) => setTimeout(cb, 1));

  whenIdle(() => {
    for (const tag of TAGS) {
      if (!consent[tag.consent]) continue;

      const script = document.createElement('script');
      script.src = tag.src;
      script.async = true;
      // A third-party outage must not become our outage.
      script.onerror = () => report('third_party.failed', { id: tag.id });
      document.body.append(script);
    }
  });
}

/**
 * Runs in CI against a real load. A tag that grew past its budget shows up
 * as a failing build rather than as a slow product page nobody attributes
 * to the tag added three sprints ago.
 */
export async function auditTagSizes(page: Page) {
  const transferred = await measureTransferByOrigin(page);

  for (const tag of TAGS) {
    const kb = transferred[new URL(tag.src).origin] ?? 0;
    if (kb > tag.maxKb) {
      throw new Error(`${tag.id}: ${kb}kB exceeds its ${tag.maxKb}kB budget`);
    }
  }
}
